// WF-6 — dual write: swarm_log + Qdrant (E7-1, E7-2)
// Input: full state with outcome.status, candidate, test, audit
const inp = $input.first().json;
const state = inp.state || inp;
const isTool = state.outcome?.status === 'deployed' && state.candidate?.code;
const isFailure = state.outcome?.status === 'failed' || (state.loop?.remaining === 0 && !state.candidate);
let collection = null;
let payload = null;
let textToEmbed = '';
if (isTool) {
  collection = 'tool_store';
  payload = {
    type: 'tool',
    tool_name: state.candidate.tool_name,
    code: state.candidate.code,
    description: state.candidate.description,
    input_schema: state.candidate.input_schema,
    fitness: 1,
    goal: state.goal
  };
  textToEmbed = `${state.candidate.description} ${state.goal}`;
} else if (isFailure) {
  collection = 'problem_store';
  const lastRun = state.test?.runs?.[state.test.runs.length-1] || {};
  payload = {
    type: 'failure',
    goal: state.goal,
    error: lastRun.stderr || state.outcome?.final_answer || 'unknown',
    code_summary: (state.candidate?.code||'').slice(0,300),
    date: new Date().toISOString()
  };
  textToEmbed = `${state.goal} ${payload.error}`;
}
// Always prepare swarm_log row too
const row = {
  task_id: state.task_id || 'unknown',
  workflow: isTool ? 'tool_store' : (isFailure ? 'problem_store' : 'swarm_log'),
  gate: state.loop?.gate || 'unknown',
  verdict: state.outcome?.status || 'unknown',
  duration_ms: 0
};
return [{ json: { state, collection, payload, textToEmbed, row, isTool, isFailure } }];
